cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Apply standard shipping: cost = 6, new total = subtotal - discount + gift_wrap - loyalty + shipping
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
const shippingCost = 6;
const newTotal = cart.subtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + shippingCost;

db.prepare(\"UPDATE carts SET shipping_option = 'standard', shipping_cost = ?, total = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(shippingCost, newTotal);

// Verify
const updated = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log(JSON.stringify(updated, null, 2));
db.close();
"

