  sheets.add(key.split(':')[0]);
}
console.log('Sheets found:', [...sheets]);

// Check if there's a Cart sheet
for (const key of Object.keys(cells).sort()) {
  if (key.startsWith('Cart')) console.log(key, '=', cells[key]);
}
